 /** A renamed bytecode fixture carries the same source/helper/Operation shape as the production final verifier.
  * The source bodies below are independently compiled counters/throws/nesting, rather than a fabricated token. */
 private record Seam(MethodNode originalUnder,MethodNode originalGround,MethodNode under,MethodNode ground,MethodInsnNode underAnchor,MethodInsnNode groundAnchor){ }
