  MethodNode g=new MethodNode(Opcodes.ACC_PRIVATE,"standing","(Ljava/lang/Object;L"+OWNER+";)Z",null,null);unique(g);g.instructions.add(new VarInsnNode(Opcodes.ALOAD,2));g.instructions.add(new FieldInsnNode(Opcodes.GETSTATIC,OWNER,"TAG","Ljava/lang/Object;"));g.instructions.add(call(ga));g.instructions.add(new InsnNode(Opcodes.IRETURN));
  MethodNode finalU=copy(u);MethodInsnNode anchor=Arrays.stream(finalU.instructions.toArray()).filter(i->i instanceof MethodInsnNode m&&m.name.equals(ua.name)).map(MethodInsnNode.class::cast).findFirst().orElseThrow();InsnList injected=new InsnList();injected.add(new VarInsnNode(Opcodes.ALOAD,0));injected.add(new InsnNode(Opcodes.SWAP));injected.add(new VarInsnNode(Opcodes.ALOAD,1));injected.add(new MethodInsnNode(Opcodes.INVOKESPECIAL,OWNER,sourceUnder.name,sourceUnder.desc,false));finalU.instructions.insert(anchor,injected);
