  MethodNode relay=new MethodNode(Opcodes.ACC_PRIVATE|Opcodes.ACC_STATIC|Opcodes.ACC_SYNTHETIC,"relay","([Ljava/lang/Object;)Ljava/lang/Boolean;",null,null);relay.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));relay.instructions.add(new InsnNode(Opcodes.ICONST_0));relay.instructions.add(new InsnNode(Opcodes.AALOAD));relay.instructions.add(new TypeInsnNode(Opcodes.CHECKCAST,OWNER));relay.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));relay.instructions.add(new InsnNode(Opcodes.ICONST_1));relay.instructions.add(new InsnNode(Opcodes.AALOAD));relay.instructions.add(new TypeInsnNode(Opcodes.CHECKCAST,"java/lang/Object"));relay.instructions.add(call(ga));relay.instructions.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"java/lang/Boolean","valueOf","(Z)Ljava/lang/Boolean;",false));relay.instructions.add(new InsnNode(Opcodes.ARETURN));
