 private static void unique(MethodNode method){method.visibleAnnotations=new ArrayList<>(List.of(new AnnotationNode("Lorg/spongepowered/asm/mixin/Unique;")));}
 private static void merged(MethodNode method){if(method.visibleAnnotations==null)method.visibleAnnotations=new ArrayList<>();AnnotationNode merged=new AnnotationNode("Lorg/spongepowered/asm/mixin/transformer/meta/MixinMerged;");merged.values=new ArrayList<>(List.of("mixin",OWNER.replace('/','.')));method.visibleAnnotations.add(merged);}
 private static MethodNode copy(MethodNode method){MethodNode copy=new MethodNode(method.access,method.name,method.desc,null,null);method.accept(copy);for(AbstractInsnNode instruction:copy.instructions)if(instruction instanceof InvokeDynamicInsnNode dynamic)dynamic.bsmArgs=dynamic.bsmArgs.clone();return copy;}
 private static MethodInsnNode call(MethodInsnNode instruction){return new MethodInsnNode(instruction.getOpcode(),instruction.owner,instruction.name,instruction.desc,instruction.itf);}
 private static byte[]write(ClassNode owner){ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS);owner.accept(writer);return writer.toByteArray();}
 private static Object object(Fixture f)throws Throwable{Object mirror=InjectorExecution.construct(f.loader.loadClass(OWNER.replace('/','.')));set(mirror,"key",f.key);return mirror;}
 private static void set(Object receiver,String name,Object value)throws Exception{receiver.getClass().getField(name).set(receiver,value);}private static Object field(Object receiver,String name)throws Exception{return receiver.getClass().getField(name).get(receiver);}
 private static List<Integer>callOffsets(MethodNode method,String target){List<Integer>result=new ArrayList<>();int offset=0;for(var instruction:method.instructions){if(instruction.getOpcode()<0)continue;if(instruction instanceof MethodInsnNode call){if(call.name.equals(target))result.add(offset);offset+=call.getOpcode()==Opcodes.INVOKEINTERFACE?5:3;}else if(instruction instanceof FieldInsnNode||instruction instanceof TypeInsnNode||instruction instanceof JumpInsnNode)offset+=3;else if(instruction instanceof VarInsnNode variable){assertTrue(variable.var<256);offset+=variable.var<4?1:2;}else if(instruction instanceof InsnNode)offset++;else throw new AssertionError("unproved bytecode width "+instruction);}return result;}
 private static MethodContract contract(String owner,MethodNode method){return new MethodContract(owner,method.name,method.desc,DefinedMethodContracts.fingerprint(method));}
 private static MethodNode method(ClassNode owner,String name,String desc){return owner.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElseThrow();}
 private static ClassNode parse(byte[]bytes){ClassNode node=new ClassNode();new ClassReader(bytes).accept(node,ClassReader.EXPAND_FRAMES);return node;}
